        deps!();
        impl < 'tcx > UniversalRegions < 'tcx > { # [doc = " Creates a new and fully initialized `UniversalRegions` that"] # [doc = " contains indices for all the free regions found in the given"] # [doc = " MIR -- that is, all the regions that appear in the function's"] # [doc = " signature. This will also compute the relationships that are"] # [doc = " known between those regions."] pub (crate) fn new (infcx : & BorrowckInferCtxt < 'tcx > , mir_def : LocalDefId) -> Self { UniversalRegionsBuilder { infcx , mir_def } . build () } # [doc = " Given a reference to a closure type, extracts all the values"] # [doc = " from its free regions and returns a vector with them. This is"] # [doc = " used when the closure's creator checks that the"] # [doc = " `ClosureRegionRequirements` are met. The requirements from"] # [doc = " `ClosureRegionRequirements` are expressed in terms of"] # [doc = " `RegionVid` entries that map into the returned vector `V`: so"] # [doc = " if the `ClosureRegionRequirements` contains something like"] # [doc = " `'1: '2`, then the caller would impose the constraint that"] # [doc = " `V[1]: V[2]`."] pub (crate) fn closure_mapping (tcx : TyCtxt < 'tcx > , closure_args : GenericArgsRef < 'tcx > , expected_num_vars : usize , closure_def_id : LocalDefId ,) -> IndexVec < RegionVid , ty :: Region < 'tcx > > { let mut region_mapping = IndexVec :: with_capacity (expected_num_vars) ; region_mapping . push (tcx . lifetimes . re_static) ; tcx . for_each_free_region (& closure_args , | fr | { region_mapping . push (fr) ; }) ; for_each_late_bound_region_in_recursive_scope (tcx , tcx . local_parent (closure_def_id) , | r | { region_mapping . push (r) ; }) ; assert_eq ! (region_mapping . len () , expected_num_vars , "index vec had unexpected number of variables") ; region_mapping } # [doc = " Returns `true` if `r` is a member of this set of universal regions."] pub (crate) fn is_universal_region (& self , r : RegionVid) -> bool { (FIRST_GLOBAL_INDEX .. self . num_universals) . contains (& r . index ()) } # [doc = " Classifies `r` as a universal region, returning `None` if this"] # [doc = " is not a member of this set of universal regions."] pub (crate) fn region_classification (& self , r : RegionVid) -> Option < RegionClassification > { let index = r . index () ; if (FIRST_GLOBAL_INDEX .. self . first_extern_index) . contains (& index) { Some (RegionClassification :: Global) } else if (self . first_extern_index .. self . first_local_index) . contains (& index) { Some (RegionClassification :: External) } else if (self . first_local_index .. self . num_universals) . contains (& index) { Some (RegionClassification :: Local) } else { None } } # [doc = " Returns an iterator over all the RegionVids corresponding to"] # [doc = " universally quantified free regions."] pub (crate) fn universal_regions_iter (& self) -> impl Iterator < Item = RegionVid > + 'static { (FIRST_GLOBAL_INDEX .. self . num_universals) . map (RegionVid :: from_usize) } # [doc = " Returns `true` if `r` is classified as a local region."] pub (crate) fn is_local_free_region (& self , r : RegionVid) -> bool { self . region_classification (r) == Some (RegionClassification :: Local) } # [doc = " Returns the number of universal regions created in any category."] pub (crate) fn len (& self) -> usize { self . num_universals } # [doc = " Returns the number of global plus external universal regions."] # [doc = " For closures, these are the regions that appear free in the"] # [doc = " closure type (versus those bound in the closure"] # [doc = " signature). They are therefore the regions between which the"] # [doc = " closure may impose constraints that its creator must verify."] pub (crate) fn num_global_and_external_regions (& self) -> usize { self . first_local_index } # [doc = " Gets an iterator over all the early-bound regions that have names."] pub (crate) fn named_universal_regions_iter (& self ,) -> impl Iterator < Item = (ty :: Region < 'tcx > , ty :: RegionVid) > { self . indices . indices . iter () . map (| (& r , & v) | (r , v)) } # [doc = " See [UniversalRegionIndices::to_region_vid]."] pub (crate) fn to_region_vid (& self , r : ty :: Region < 'tcx >) -> RegionVid { self . indices . to_region_vid (r) } # [doc = " As part of the NLL unit tests, you can annotate a function with"] # [doc = " `#[rustc_regions]`, and we will emit information about the region"] # [doc = " inference context and -- in particular -- the external constraints"] # [doc = " that this region imposes on others. The methods in this file"] # [doc = " handle the part about dumping the inference context internal"] # [doc = " state."] pub (crate) fn annotate (& self , tcx : TyCtxt < 'tcx > , err : & mut Diag < '_ , () >) { match self . defining_ty { DefiningTy :: Closure (def_id , args) => { let v = with_no_trimmed_paths ! (args [tcx . generics_of (def_id) . parent_count ..] . iter () . map (| arg | arg . to_string ()) . collect ::< Vec < _ >> ()) ; err . note (format ! ("defining type: {} with closure args [\n    {},\n]" , tcx . def_path_str_with_args (def_id , args) , v . join (",\n    ") ,)) ; for_each_late_bound_region_in_recursive_scope (tcx , def_id . expect_local () , | r | { err . note (format ! ("late-bound region is {:?}" , self . to_region_vid (r))) ; }) ; } DefiningTy :: CoroutineClosure (..) => { todo ! () } DefiningTy :: Coroutine (def_id , args) => { let v = with_no_trimmed_paths ! (args [tcx . generics_of (def_id) . parent_count ..] . iter () . map (| arg | arg . to_string ()) . collect ::< Vec < _ >> ()) ; err . note (format ! ("defining type: {} with coroutine args [\n    {},\n]" , tcx . def_path_str_with_args (def_id , args) , v . join (",\n    ") ,)) ; for_each_late_bound_region_in_recursive_scope (tcx , def_id . expect_local () , | r | { err . note (format ! ("late-bound region is {:?}" , self . to_region_vid (r))) ; }) ; } DefiningTy :: FnDef (def_id , args) => { err . note (format ! ("defining type: {}" , tcx . def_path_str_with_args (def_id , args) ,)) ; } DefiningTy :: Const (def_id , args) => { err . note (format ! ("defining constant type: {}" , tcx . def_path_str_with_args (def_id , args) ,)) ; } DefiningTy :: InlineConst (def_id , args) => { err . note (format ! ("defining inline constant type: {}" , tcx . def_path_str_with_args (def_id , args) ,)) ; } DefiningTy :: GlobalAsm (_) => unreachable ! () , } } pub (crate) fn implicit_region_bound (& self) -> RegionVid { self . fr_fn_body } pub (crate) fn encountered_re_error (& self) -> Option < ErrorGuaranteed > { self . indices . encountered_re_error . get () } }
